"""Public package surface for kestrel-kernels."""

import os as _os
import sys as _sys
from pathlib import Path as _Path
from typing import Any

# Import torch eagerly so its Windows DLL search-path setup runs before any
# kestrel kernel DLL gets loaded. Torch's __init__ calls os.add_dll_directory
# for torch/lib (which holds the bundled cublasLt64_12.dll) and the CUDA
# toolkit path; without that, our C kernels that link against cuBLASLt fail
# to load with Win32 error 126. The directories stay registered for the
# rest of the process, so subsequent LoadLibrary calls in _pybridge inherit
# the search path.
import torch

# Side effect: installs ``__dlpack_c_exchange_api__`` on ``torch.Tensor`` so
# any ``_pybridge`` kernel call (Mode-1 or Mode-2) can pack tensors via DLPack.
from kestrel_kernels._dlpack import ensure_dlpack_c_exchange_api

ensure_dlpack_c_exchange_api()

# On Windows, also register this package's own directory so that kernel
# DLLs in this folder can resolve sibling-DLL dependencies (e.g.
# kestrel_cublas_lt_workspace.dll, which fused_mlp/fused_linear link
# against). _pybridge's LoadLibraryExW call uses LOAD_LIBRARY_SEARCH_USER_DIRS,
# which only consults paths registered via AddDllDirectory.
if _sys.platform == "win32":
    _os.add_dll_directory(_os.path.dirname(__file__))


# ---------------------------------------------------------------------------
# Multi-CUDA wheel layout: Linux wheels may ship parallel kernel-library trees
# under ``cu<major>/`` for each supported CUDA major. Mode-2 cubin/AOT bundles
# live under ``cu<major>/bundles/``. Depending on the wheel builder, Mode-1
# shared libraries may live alongside those bundles or at the package root.
# We pick the Mode-2 tree from ``torch.version.cuda`` and independently locate
# Mode-1 libraries for ``_pybridge``.
# Standalone single-CUDA builds may keep the legacy flat layout — ``KERNEL_DIR``
# then points at the package root and Mode-2 runtimes inherit
# ``<package>/bundles``.
# ---------------------------------------------------------------------------

_PKG_ROOT: _Path = _Path(__file__).resolve().parent
_PLATFORM = _sys.platform


def _detect_cuda_major() -> int | None:
    cv = getattr(torch.version, "cuda", None)
    if not cv:
        return None
    try:
        return int(cv.split(".")[0])
    except (ValueError, IndexError):
        return None


def _select_kernel_dir() -> _Path:
    major = _detect_cuda_major()
    if major is not None:
        candidate = _PKG_ROOT / f"cu{major}"
        if candidate.is_dir():
            return candidate
    # Either CPU/MPS torch (no CUDA) or a single-CUDA wheel (flat layout).
    # If the wheel only ships ``cu<other>`` subdirs and torch's CUDA major
    # doesn't match, raise rather than silently falling back to a layout
    # that has no kernel libs at all.
    available = sorted(p.name for p in _PKG_ROOT.iterdir()
                       if p.is_dir() and p.name.startswith("cu")
                       and p.name[2:].isdigit())
    if available and major is not None:
        hint = (
            "Install a kestrel-kernels wheel matching your torch CUDA major, "
            "or install a PyTorch build matching one of the CUDA builds this "
            "wheel ships."
        )
        if major >= 13 and available == ["cu12"]:
            hint = (
                "This usually means pip selected the CUDA 12 compatibility "
                "wheel, which can happen on older Linux/glibc platforms that "
                "cannot install the CUDA 13 wheel. The CUDA 13 wheel requires "
                "glibc 2.35 or newer (for example Ubuntu 22.04+). Use a newer "
                "Linux image, or install a CUDA 12.8 PyTorch build."
            )
        raise ImportError(
            f"kestrel_kernels: no kernel build for CUDA {major}; this wheel "
            f"ships builds for: {available}. {hint}"
        )
    return _PKG_ROOT


KERNEL_DIR: _Path = _select_kernel_dir()


def _has_mode1_libraries(directory: _Path, platform: str) -> bool:
    patterns = {
        "win32": "*.dll",
        "darwin": "lib*.dylib",
    }
    pattern = patterns.get(platform, "lib*.so")
    return any(path.is_file() for path in directory.glob(pattern))


def _select_mode1_kernel_dir(
    kernel_dir: _Path,
    package_root: _Path,
    platform: str,
) -> _Path:
    """Locate linked Mode-1 libraries without changing the Mode-2 bundle root."""
    if _has_mode1_libraries(kernel_dir, platform):
        return kernel_dir
    if kernel_dir != package_root and _has_mode1_libraries(package_root, platform):
        return package_root
    # Preserve the selected CUDA directory when neither layout is populated so
    # a missing library error names the wheel tree that should have contained it.
    return kernel_dir


def _register_kernel_dir() -> None:
    """Tell the C extension which directory holds Mode-1 kernel libs.

    Only needed for the multi-CUDA subdir layout. On flat-layout wheels
    (single-CUDA x86_64 and non-CUDA macOS/CPU), the C side's default
    lookup — relative to ``kestrel_kernels.__file__`` — is already
    correct, so we skip the call entirely. This also avoids invoking
    the ``_pybridge.py`` shim on non-CUDA wheels: the shim's
    ``__getattr__`` returns a stub callable for *any* attribute, so the
    import succeeds even when the C extension is absent, and calling
    the stub raises ``RuntimeError``.
    """
    mode1_dir = _select_mode1_kernel_dir(KERNEL_DIR, _PKG_ROOT, _PLATFORM)
    if mode1_dir == _PKG_ROOT:
        return
    try:
        from kestrel_kernels._pybridge import _set_kernel_dir
    except ImportError:
        return
    _set_kernel_dir(str(mode1_dir))


_register_kernel_dir()
del _os, _sys, _Path

__all__ = [
    "KERNEL_DIR",
    "KernelRuntime",
    "get_runtime",
]


def __getattr__(name: str) -> Any:
    if name in {"KernelRuntime", "get_runtime"}:
        from kestrel_kernels.runtime import KernelRuntime, get_runtime

        exports = {
            "KernelRuntime": KernelRuntime,
            "get_runtime": get_runtime,
        }
        return exports[name]
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
